files.content:
plugins {
    id("com.android.application") version "8.5.2" apply false
    id("org.jetbrains.kotlin.android") version "2.0.20" apply false
    id("org.jetbrains.kotlin.plugin.serialization") version "2.0.20" apply false
}

allprojects {
    repositories {
        google()
        mavenCentral()
        maven(url = "https://jitpack.io")
    }
}

android {
    compileSdk 34

    defaultConfig {
        minSdk 21
        targetSdk 34

        versionCode ext.extVersionCode as Integer
        versionName "${ext.libVersion}.${ext.extVersionCode}"
        applicationId "eu.kanade.tachiyomi.extension.${ext.pkgNameSuffix}"
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }

    kotlinOptions {
        jvmTarget = "1.8"
        freeCompilerArgs += "-opt-in=kotlinx.serialization.ExperimentalSerializationApi"
    }

    sourceSets {
        main {
            manifest.srcFile "AndroidManifest.xml"
            java.srcDirs = ["src"]
            res.srcDirs = ["res"]
        }
    }
}

dependencies {
    compileOnly "com.github.tachiyomiorg:extensions-lib:1.4"
    implementation "org.jsoup:jsoup:1.17.2"
    implementation "com.squareup.okhttp3:okhttp:4.12.0"
    implementation "io.reactivex:rxjava:1.3.8"
}

{
  "meta": {
    "name": "Turkish Manga Extensions (Tachimanga / Mihon)",
    "description": "Tachimanga (iOS) ve Mihon için bağımsız çalışan Türkçe manga uzantıları (Jura Tempest, Mangtto, Ori Manga, Gölge Bahçesi).",
    "website": "https://github.com/songulysnkmsr-blip/tempestrepo"
  }
}

